#!/usr/bin/env node
// Generated by OrchestKit Claude Plugin
// Created: 2026-10-28
/**
 * spawn-ratchet.mjs: how many hook processes one tool call starts.
 *
 * Every `type: "command"` entry in hooks.json is one node process per match.
 * This gate counts, per tool (Bash, Edit, Write, Read) and per path, the
 * command entries whose matcher matches the tool, straight from hooks.json:
 *
 *   success     PreToolUse + PostToolUse + PostToolBatch
 *   permission  success + PermissionRequest (the call raised a prompt)
 *   failure     PreToolUse + PostToolUseFailure + PostToolBatch
 *
 * PostToolBatch is counted once per call (a batch of one), the worst case.
 * The counts are static and deterministic; no hook is run.
 *
 * Two checks, same shape as hq-ext scripts/ci/check-hook-spawn-ratchet.py:
 *   ratchet  a count above spawn-ratchet-baseline.json fails (remove the
 *            spawn or raise the baseline in the PR, with the reason); a count
 *            below it fails too, asking for the lower baseline in the same PR
 *            (`--update`), so the win is locked at merge.
 *   target   a success-path count above `target` fails. The target is the
 *            yellow-refactor finish line (under 3 processes per tool call).
 *
 * Matcher semantics follow Claude Code: absent, "" or "*" matches every tool;
 * a matcher of word characters and "|" is an exact list; anything else is an
 * anchored regular expression.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { unifiedToolHooks } from './unified-pretool-hooks.mjs';

const __dirname = dirname(fileURLToPath(import.meta.url));
const HOOKS_JSON = join(__dirname, '..', 'hooks.json');
const BASELINE_PATH = join(__dirname, 'spawn-ratchet-baseline.json');

const TOOLS = ['Bash', 'Edit', 'Write', 'Read'];
const PATHS = {
  success: ['PreToolUse', 'PostToolUse', 'PostToolBatch'],
  permission: ['PreToolUse', 'PermissionRequest', 'PostToolUse', 'PostToolBatch'],
  failure: ['PreToolUse', 'PostToolUseFailure', 'PostToolBatch'],
};

export function matches(matcher, tool) {
  if (matcher === undefined || matcher === '' || matcher === '*') return true;
  if (/^[\w|]+$/.test(matcher)) return matcher.split('|').includes(tool);
  return new RegExp(`^(?:${matcher})$`).test(tool);
}

export function countSpawns(hooksDoc, tool, events) {
  let n = 0;
  for (const event of events) {
    for (const entry of hooksDoc.hooks[event] ?? []) {
      if (!matches(entry.matcher, tool)) continue;
      n += (entry.hooks ?? []).filter((h) => h.type === 'command').length;
    }
  }
  return n;
}

export function measure(hooksDoc) {
  const out = {};
  for (const path of Object.keys(PATHS)) {
    out[path] = {};
    for (const tool of TOOLS) out[path][tool] = countSpawns(hooksDoc, tool, PATHS[path]);
  }
  return out;
}

// `flagged` is the count for the dispatcher variant (unified-pretool-hooks.mjs),
// the hooks.json the flag ships. The target is that variant's finish line; the
// ratchet stays on the shipped hooks.json, which the flag leaves unchanged.
export function compare(measured, baseline, target, flagged = measured) {
  const lines = [];
  let failed = false;
  for (const path of Object.keys(PATHS)) {
    for (const tool of TOOLS) {
      const got = measured[path][tool];
      const want = baseline[path]?.[tool];
      if (want === undefined) {
        failed = true;
        lines.push(`MISSING ${path}.${tool}: measured ${got}, no baseline`);
      } else if (got > want) {
        failed = true;
        lines.push(`ROSE  ${path}.${tool}: ${want} -> ${got} (+${got - want})`);
      } else if (got < want) {
        failed = true;
        lines.push(`FELL  ${path}.${tool}: ${want} -> ${got} (${got - want}); lock it with --update`);
      } else {
        lines.push(`ok    ${path}.${tool}: ${got}`);
      }
    }
  }
  for (const tool of TOOLS) {
    const got = flagged.success[tool];
    if (target[tool] === undefined) continue;
    if (got > target[tool]) {
      failed = true;
      lines.push(`OVER TARGET  flag-on success.${tool}: ${got} spawns per call, target <= ${target[tool]}`);
    } else {
      lines.push(`ok    flag-on success.${tool}: ${got} (target <= ${target[tool]})`);
    }
  }
  return { failed, lines };
}

function main() {
  const hooksDoc = JSON.parse(readFileSync(HOOKS_JSON, 'utf8'));
  const doc = JSON.parse(readFileSync(BASELINE_PATH, 'utf8'));
  const measured = measure(hooksDoc);
  if (process.argv.includes('--update')) {
    doc.baseline = measured;
    writeFileSync(BASELINE_PATH, `${JSON.stringify(doc, null, 2)}\n`);
    console.log(`spawn-ratchet: baseline set to ${JSON.stringify(measured)}`);
    return 0;
  }
  const flagged = measure(unifiedToolHooks(hooksDoc));
  const { failed, lines } = compare(measured, doc.baseline, doc.target, flagged);
  console.log(lines.join('\n'));
  console.log(failed ? 'spawn-ratchet: FAIL' : 'spawn-ratchet: OK');
  return failed ? 1 : 0;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  process.exit(main());
}
